import React, { useState, useEffect } from 'react';
import Navbar from '../components/Navbar';
import { useAuth } from '../contexts/AuthContext';
import axios from 'axios';
import { Loader2, FileText, MapPin, Calendar, Clock, Shield, ChevronDown, ChevronUp } from 'lucide-react';
import { motion } from 'framer-motion';

import API_URL from '../lib/api';

const statusColors = {
  submitted: 'bg-blue-100 text-blue-700',
  analyzed: 'bg-amber-100 text-amber-700',
  open: 'bg-green-100 text-green-700',
  accepted: 'bg-emerald-100 text-emerald-700',
  'in-progress': 'bg-purple-100 text-purple-700',
  resolved: 'bg-slate-100 text-slate-700',
};

const MyCases = () => {
  const { user } = useAuth();
  const [cases, setCases] = useState([]);
  const [loading, setLoading] = useState(true);
  const [expandedCase, setExpandedCase] = useState(null);

  useEffect(() => {
    fetchMyCases();
  }, []);

  const fetchMyCases = async () => {
    try {
      const { data } = await axios.get(`${API_URL}/api/my-cases`, {  });
      setCases(data);
    } catch (err) {
      console.error('Failed to fetch cases', err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100" data-testid="my-cases-page">
      <Navbar />

      <div className="max-w-5xl mx-auto px-6 py-10">
        <div className="flex items-center justify-between mb-8">
          <div>
            <h1 className="font-heading text-3xl font-bold text-slate-900" data-testid="my-cases-title">My Cases</h1>
            <p className="text-sm text-slate-500 mt-1">Track all your submitted legal cases</p>
          </div>
          <span className="text-sm bg-slate-200 text-slate-700 px-3 py-1 rounded-full font-medium">
            {cases.length} case{cases.length !== 1 ? 's' : ''}
          </span>
        </div>

        {loading ? (
          <div className="flex items-center justify-center py-20" data-testid="loading">
            <Loader2 className="w-10 h-10 text-slate-400 animate-spin" />
          </div>
        ) : cases.length === 0 ? (
          <div className="bg-white rounded-2xl border border-slate-200 p-16 text-center" data-testid="no-cases">
            <FileText className="w-12 h-12 text-slate-300 mx-auto mb-4" />
            <h3 className="text-lg font-semibold text-slate-800 mb-2">No cases yet</h3>
            <p className="text-sm text-slate-500">Submit your first case through the Intelligence Engine</p>
          </div>
        ) : (
          <div className="space-y-4" data-testid="cases-list">
            {cases.map((c, i) => (
              <motion.div
                key={c.id}
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: i * 0.05 }}
                className="bg-white rounded-xl border border-slate-200 overflow-hidden hover:shadow-md transition-shadow"
                data-testid={`case-item-${i}`}
              >
                <div
                  className="p-5 cursor-pointer"
                  onClick={() => setExpandedCase(expandedCase === c.id ? null : c.id)}
                >
                  <div className="flex items-start justify-between">
                    <div className="flex-1">
                      <div className="flex items-center gap-3 mb-2">
                        <h3 className="font-semibold text-slate-900">{c.case_type} Law</h3>
                        <span className={`text-xs font-medium px-2 py-0.5 rounded-full ${statusColors[c.case_status] || 'bg-slate-100 text-slate-600'}`}>
                          {c.case_status}
                        </span>
                        {(c.nyayId || c.nyay_id) && (
                          <span className="text-xs bg-slate-800 text-white px-2 py-0.5 rounded-full flex items-center gap-1">
                            <Shield className="w-3 h-3" /> {c.nyayId || c.nyay_id}
                          </span>
                        )}
                      </div>
                      <p className="text-sm text-slate-600 line-clamp-2">{c.description}</p>
                      <div className="flex items-center gap-4 mt-2 text-xs text-slate-400">
                        {c.location && <span className="flex items-center gap-1"><MapPin className="w-3 h-3" />{c.location}</span>}
                        <span className="flex items-center gap-1"><Calendar className="w-3 h-3" />{new Date(c.created_at).toLocaleDateString()}</span>
                        <span className="flex items-center gap-1"><Clock className="w-3 h-3" />{c.urgency}</span>
                      </div>
                    </div>
                    <div className="ml-4">
                      {expandedCase === c.id ? <ChevronUp className="w-5 h-5 text-slate-400" /> : <ChevronDown className="w-5 h-5 text-slate-400" />}
                    </div>
                  </div>
                </div>

                {expandedCase === c.id && (
                  <motion.div
                    initial={{ height: 0, opacity: 0 }}
                    animate={{ height: 'auto', opacity: 1 }}
                    className="border-t border-slate-100 px-5 py-4 bg-slate-50"
                  >
                    {c.lawyer_name && (
                      <p className="text-sm text-slate-600 mb-2">
                        Assigned Lawyer: <span className="font-medium text-slate-800">{c.lawyer_name}</span>
                      </p>
                    )}
                    {c.status_history?.length > 0 && (
                      <div>
                        <p className="text-xs font-medium text-slate-500 mb-2">Status History</p>
                        <div className="space-y-1">
                          {c.status_history.map((sh, j) => (
                            <div key={j} className="flex items-center gap-2 text-xs text-slate-500">
                              <div className="w-1.5 h-1.5 bg-slate-400 rounded-full" />
                              <span className="font-medium">{sh.status}</span>
                              <span>-</span>
                              <span>{sh.notes}</span>
                              <span className="text-slate-300">({new Date(sh.timestamp).toLocaleString()})</span>
                            </div>
                          ))}
                        </div>
                      </div>
                    )}
                  </motion.div>
                )}
              </motion.div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default MyCases;
